function setNLang(l){ nLang=l;
  var a=document.getElementById('ntFa'), b=document.getElementById('ntEn');
  if(a)a.classList.toggle('on',l==='fa'); if(b)b.classList.toggle('on',l==='en');
  renderNotes(); }
function addNote(){
  const inp=document.getElementById('nInp'), t=(inp.value||'').trim();
  if(!t){ toast(UIL==='fa'?'اول یادداشتت رو بنویس ✍️':'Write your note first ✍️'); return; }
  const sec=nowSec();
  const arr=JSON.parse(localStorage.getItem(NKEY(cur.id))||'[]');
  arr.push({t,sec,lang:nLang,at:Date.now()});
  localStorage.setItem(NKEY(cur.id),JSON.stringify(arr));
  inp.value=''; renderNotes(); toast(UIL==='fa'?('✅ یادداشت در ⏱ '+fmtT(sec)+' ذخیره شد'):('✅ Note saved at '+fmtT(sec)));
}
function renderNotes(){
  const box=document.getElementById('nList'); if(!box) return;
  const all=JSON.parse(localStorage.getItem(NKEY(cur.id))||'[]');
  const arr=all.filter(n=>n.lang===nLang);
  box.innerHTML=arr.length?arr.map(n=>{
    const gi=all.indexOf(n);
    return `<div class="vnote"><button class="xx" onclick="delNote(${gi})">×</button><span class="tt" onclick="seek(${n.sec})">⏱ ${fmtT(n.sec)}</span>${esc(n.t)}<span class="dd">${new Date(n.at).toLocaleString(UIL==='fa'?'fa-IR':'en-US')}</span></div>`;
  }).join(''):T('noteEmpty');
}
function delNote(gi){
  const all=JSON.parse(localStorage.getItem(NKEY(cur.id))||'[]');
  all.splice(gi,1); localStorage.setItem(NKEY(cur.id),JSON.stringify(all)); renderNotes();
}
function setQLang(l){ qLang=l;
  var a=document.getElementById('qtFa'), b=document.getElementById('qtEn');
  if(a)a.classList.toggle('on',l==='fa'); if(b)b.classList.toggle('on',l==='en');
  renderQuiz(); }
function renderQuizLegacy(){
  const box=document.getElementById('qBox'); if(!box) return;
  const idx=VIDEOS.indexOf(cur), qs=QUIZ.slice(idx*3,idx*3+3);
  box.dataset.done='0'; box.dataset.score='0';
  box.innerHTML=`<div class="qscore" id="qScore">${T('qHead')}</div>`+qs.map((q,i)=>{
    const Q=qLang==='fa'?q.qf:q.qe;
    const O=qLang==='fa'?q.of:q.oe, W=qLang==='fa'?q.wf:q.we;
    const qdir=qLang==='en'?' style="direction:ltr;text-align:left"':'';
    const qnum=qLang==='fa'?fa2(i+1):String(i+1);
    return `<div class="q" id="qq${i}"><h4${qdir}>${qnum}. ${esc(Q)}</h4>`
      +O.map((o,j)=>`<button class="opt${qLang==='en'?' en':''}" onclick="ans(${i},${j},${q.c},this)">${esc(o)}</button>`).join('')
      +`<div class="why${qLang==='en'?' en':''}" id="qw${i}">💡 ${esc(W)}`+(q.ts!=null?`<button type="button" class="qjump" onclick="seek(${q.ts})">⏱ ${fmtT(q.ts)} — ${qLang==='fa'?'پرش به همین لحظه در ویدیو':'jump to the answer in the video'}</button>`:'')+`</div></div>`;
  }).join('');
}
function ans(i,j,c,btn){
  const card=document.getElementById('qq'+i);
  if(!card||card.dataset.done) return; card.dataset.done='1';
  const opts=card.querySelectorAll('.opt');
  opts.forEach(b=>b.disabled=true);
  if(j===c){ btn.classList.add('ok'); } else { btn.classList.add('no'); opts[c].classList.add('ok'); }
  document.getElementById('qw'+i).classList.add('show');
  const box=document.getElementById('qBox');
  box.dataset.done=+box.dataset.done+1;
  if(j===c) box.dataset.score=+box.dataset.score+1;
  if(+box.dataset.done===3){
    const s=+box.dataset.score;
    document.getElementById('qScore').textContent=UIL==='fa'?('نمره‌ت: '+fa2(s)+' از '+fa2(3)+(s===3?' 🎉 عالی!':s===2?' 👍 خوبه':' 📚 یه دور دیگه ببین')):('Your score: '+s+' / 3'+(s===3?' 🎉 Excellent!':s===2?' 👍 Good':' 📚 Watch again'));
  }
}
