/* ---- hover preview on cards ---- */
let pvTimer=null;
function pvKill(){var fs=document.querySelectorAll('.pvfr');for(var i=0;i<fs.length;i++){if(fs[i].parentNode)fs[i].parentNode.removeChild(fs[i]);}}
function pvBind(g){ if(!g||!g.querySelectorAll) return; var cs=g.querySelectorAll('.card');
  for(var i=0;i<cs.length;i++){ (function(card){
    card.addEventListener('mouseenter',function(){ pvHover(card,true); });
    card.addEventListener('mouseleave',function(){ pvHover(card,false); });
    card.addEventListener('click',function(){ pvKill(); });
  })(cs[i]); } }
function pvHover(card,on){
  var th=card.querySelector('.thumb'); if(!th) return;
  if(!on){ if(pvTimer)clearTimeout(pvTimer); var f=th.querySelector('.pvfr'); if(f&&f.parentNode)f.parentNode.removeChild(f); return; }
  var id=card.getAttribute('data-vid'); if(!id) return;
  if(pvTimer)clearTimeout(pvTimer);
  pvTimer=setTimeout(function(){
    if(!th||!document.body.contains(card)||th.querySelector('.pvfr')) return;
    var f=document.createElement('iframe');
    f.className='pvfr'; f.setAttribute('frameborder','0'); f.setAttribute('tabindex','-1');
    f.setAttribute('allow','autoplay; encrypted-media');
    var qs='autoplay=1&mute=1&controls=0&loop=1&playlist='+id+'&start=15&modestbranding=1&rel=0&playsinline=1&iv_load_policy=3';
    if(location.origin&&location.origin!=='null') qs+='&origin='+encodeURIComponent(location.origin);
    f.src='https://www.youtube.com/embed/'+id+'?'+qs;
    th.insertBefore(f,th.firstChild);
  },300);
}

